```cpp
  // Get the four vertices of the tetrahedron (cell)
  RT::Vertex_handle v0 = c->vertex(0);
  RT::Vertex_handle v1 = c->vertex(1);
  RT::Vertex_handle v2 = c->vertex(2);
  RT::Vertex_handle v3 = c->vertex(3);

  // Get weighted points
  Weighted_point const& p0 = v0->point();
  Weighted_point const& p1 = v1->point();
  Weighted_point const& p2 = v2->point();
  Weighted_point const& p3 = v3->point();

  // Create lifted points in 4D: (x, y, z, x²+y²+z² - w)
  LiftedPoint l0 = lifted_point(p0.x(), p0.y(), p0.z(), p0.weight());
  LiftedPoint l1 = lifted_point(p1.x(), p1.y(), p1.z(), p1.weight());
  LiftedPoint l2 = lifted_point(p2.x(), p2.y(), p2.z(), p2.weight());
  LiftedPoint l3 = lifted_point(p3.x(), p3.y(), p3.z(), p3.weight());

  // Compute the hyperplane through these four lifted points
  HyperPlane plane = CGAL::hyperplane(l0, l1, l2, l3);

  // Get the normal vector of the hyperplane (in 4D)
  LiftedPoint normal_4d = plane.orthogonal_vector();

  // The first three components give the velocity direction in 3D
  // The fourth component is related to the weight difference
  double vx = normal_4d[0];
  double vy = normal_4d[1];
  double vz = normal_4d[2];

  // Normalize to get unit vector (optional, depending on convention)
  double norm = std::sqrt(vx*vx + vy*vy + vz*vz);
  if (norm > 0) {
    vx /= norm;
    vy /= norm;
    vz /= norm;
  }

  return Vector(vx, vy, vz);
